+// Picks "ko" or "en" from an Accept-Language header (q-values and region tags
+// honored); anything else falls back to the configured default.
+function pickLanguage(headers) {
+  const key = Object.keys(headers).find((k) => k.toLowerCase() === "accept-language");
+  const raw = key ? headers[key] : "";
+  const ranked = String(raw)
+    .split(",")
+    .map((part, index) => {
+      const [tag, ...params] = part.trim().split(";");
+      const q = params.map((p) => p.trim().match(/^q=(\d*\.?\d+)$/i)).find(Boolean);
+      return { lang: tag.trim().toLowerCase().split("-")[0], q: q ? Number(q[1]) : 1, index };
+    })
+    .filter((r) => r.q > 0 && (r.lang === "ko" || r.lang === "en"))
+    .sort((a, b) => b.q - a.q || a.index - b.index);
+  return ranked.length ? ranked[0].lang : config.defaultLanguage;
+}
